def solve(name):
    if name == None:
        name = "you"
    return "One for " + name + ", one for me."

def solve(number):
    sound = ""
    if number % 3 == 0:
        sound += "Pling"
    if number % 5 == 0:
        sound += "Plang"
    if number % 7 == 0:
        sound += "Plong"
    if sound == "":
        return str(number)
    return sound

def solve(number):
    total = sum(range(1, number + 1))
    return total * total

def solve(number):
    total = 0
    for n in range(1, number + 1):
        total += n * n
    return total

def solve(sentence):
    for letter in "abcdefghijklmnopqrstuvwxyz":
        if letter not in sentence.lower():
            return False
    return True

def solve(phrase):
    seen = ""
    for letter in phrase.lower():
        if letter in "abcdefghijklmnopqrstuvwxyz":
            if letter in seen:
                return False
            seen += letter
    return True

def solve(number):
    steps = 0
    while number != 1:
        if number % 2 == 0:
            number = number // 2
        else:
            number = 3 * number + 1
        steps += 1
    return steps

def solve(colors):
    digits = {"black":0, "brown":1, "red":2, "orange":3, "yellow":4, "green":5, "blue":6, "violet":7, "grey":8, "white":9}
    return digits[colors[0]] * 10 + digits[colors[1]]

def solve(x, y):
    distance = x*x + y*y
    if distance <= 1:
        return 10
    if distance <= 25:
        return 5
    if distance <= 100:
        return 1
    return 0

def solve(number):
    digits = str(number)
    total = 0
    for digit in digits:
        total += int(digit) ** len(digits)
    return total == number
